            }
            if (_bindersByRowKey.Count > seen.Count)
            {
                var toRemove = new List<string>();
                foreach (var kv in _bindersByRowKey)
                {
                    if (!seen.Contains(kv.Key)) toRemove.Add(kv.Key);
                }
                foreach (var rowKey in toRemove)
                {
                    var binder = _bindersByRowKey[rowKey];
                    _bindersByRowKey.Remove(rowKey);
                    _binders.Remove(binder);
                    ItemRemoved?.Invoke(binder);
                    binder.Dispose();
                }
            }
            SortBinders();
        }

        private async Task<EnergyBinder> BuildBinderFromExchangeEnergyConsumeMasterItem(EzRateModel item, CancellationToken cancellationToken)
        {
            var model = EnergyBinder.CreateModel((string.IsNullOrEmpty(item.Name) ? default(EnergyId) : new EnergyId(item.Name)));
            ApplyExchangeEnergyConsumeMasterItemTo(model, item);
            var binder = new EnergyBinder(model, _gs2, _session);
            await binder.MountAsync(cancellationToken);
            return binder;
        }

        private static void ApplyExchangeEnergyConsumeMasterItemTo(MutableEnergy model, EzRateModel item)
        {
            // This loader carries no master-item field assignments; reconcile manages
            // membership only (per-element field changes are tracked by each element
            // binder's own Subscribe).
            _ = item;
            _ = model;
        }

        private EnergyId ExtractExchangeEnergyConsumeMasterIdentity(EzRateModel item)
        {
            return (string.IsNullOrEmpty(item.Name) ? default(EnergyId) : new EnergyId(item.Name));
        }

        private string? ExtractExchangeEnergyConsumeMasterRowKey(EzRateModel item)
        {
            var id = ExtractExchangeEnergyConsumeMasterIdentity(item);
            if (EqualityComparer<EnergyId>.Default.Equals(id, default)) return null;
            if (string.IsNullOrEmpty(item.Name)) return null;
            return $"{item.Name}";
        }
        /// <summary>One-shot Create + MountFromStaminaEnergyUserDataAsync (no subscription).</summary>
        public static async Task<EnergyBinderCollection> CreateFromStaminaEnergyUserDataAsync(
            Gs2Domain gs2,
            IGameSession session,
            CancellationToken cancellationToken = default)
        {
            var coll = new EnergyBinderCollection(gs2, session);
            await coll.MountFromStaminaEnergyUserDataAsync(cancellationToken);
            return coll;
        }

        public async Task MountFromStaminaEnergyUserDataAsync(CancellationToken cancellationToken = default)
        {
            ThrowIfDisposed();
            cancellationToken.ThrowIfCancellationRequested();
            var arrayLoader = new StaminaArrayLoader("Energy");
            var items = await arrayLoader.Load(_gs2, _session);
            cancellationToken.ThrowIfCancellationRequested();
            await ReconcileFromStaminaEnergyUserItems(items, attachChildSubscribe: false, cancellationToken);
            _mounted = true;
        }

        public void SubscribeFromStaminaEnergyUserData(Action? onChange = null, Action<Exception>? onError = null)
        {
            ThrowIfDisposed();
            if (_subscriptionActive) throw new InvalidOperationException("Already subscribed");
            _subscriptionActive = true;
            // Consumer-facing notification, wrapped once so a throwing consumer
            // callback routes to onError (or Debug) instead of escaping the
            // loader's async-void chain.
            Action notify = () =>
            {
                try { onChange?.Invoke(); }
                catch (Exception ex) { if (onError != null) onError(ex); else UnityEngine.Debug.LogException(ex); }
            };
            _onChange = notify;
            foreach (var b in _binders) b.Subscribe(notify);
            var arrayLoader = new StaminaArrayLoader("Energy");
            _unsubscribers.Add(arrayLoader.Subscribe(
                _gs2,
                _session,
                async (_, _, items) =>
                {
                    if (_disposed) return;
                    try
                    {
                        await ReconcileFromStaminaEnergyUserItems(items, attachChildSubscribe: true, CancellationToken.None);
                    }
                    catch (Exception ex)
                    {
                        if (onError != null) onError(ex); else UnityEngine.Debug.LogException(ex);
                    }
                },
                notify
            ));
        }

        private async Task ReconcileFromStaminaEnergyUserItems(IList<EzStamina> items, bool attachChildSubscribe, CancellationToken cancellationToken)
        {
            var seen = new HashSet<string>();
            foreach (var item in items)
            {
                if (_disposed) return;
                var rowKey = ExtractStaminaEnergyUserRowKey(item);
                if (rowKey == null) continue;
                seen.Add(rowKey);
                if (_bindersByRowKey.TryGetValue(rowKey, out var existing))
                {
                    ApplyStaminaEnergyUserItemTo(existing.MutableModel, item);
                }
                else
                {
                    var binder = await BuildBinderFromStaminaEnergyUserItem(item, cancellationToken);
                    if (attachChildSubscribe) binder.Subscribe(_onChange);
                    _bindersByRowKey[rowKey] = binder;
                    _binders.Add(binder);
                    ItemAdded?.Invoke(binder);
                }
            }
            if (_bindersByRowKey.Count > seen.Count)
            {
                var toRemove = new List<string>();
                foreach (var kv in _bindersByRowKey)
                {
                    if (!seen.Contains(kv.Key)) toRemove.Add(kv.Key);
                }
                foreach (var rowKey in toRemove)
                {
                    var binder = _bindersByRowKey[rowKey];
                    _bindersByRowKey.Remove(rowKey);
                    _binders.Remove(binder);
                    ItemRemoved?.Invoke(binder);
                    binder.Dispose();
                }
            }
            SortBinders();
        }

        private async Task<EnergyBinder> BuildBinderFromStaminaEnergyUserItem(EzStamina item, CancellationToken cancellationToken)
        {
            var model = EnergyBinder.CreateModel((string.IsNullOrEmpty(item.StaminaName) ? default(EnergyId) : new EnergyId(item.StaminaName)));
            ApplyStaminaEnergyUserItemTo(model, item);
            var binder = new EnergyBinder(model, _gs2, _session);
            await binder.MountAsync(cancellationToken);
            return binder;
        }

        private static void ApplyStaminaEnergyUserItemTo(MutableEnergy model, EzStamina item)
        {
            EnergyBinder.ApplyUserdataStaminaEnergyStaminaModel(model, item);
        }

        private EnergyId ExtractStaminaEnergyUserIdentity(EzStamina item)
        {
            return (string.IsNullOrEmpty(item.StaminaName) ? default(EnergyId) : new EnergyId(item.StaminaName));
        }

        private string? ExtractStaminaEnergyUserRowKey(EzStamina item)
        {
            var id = ExtractStaminaEnergyUserIdentity(item);
            if (EqualityComparer<EnergyId>.Default.Equals(id, default)) return null;
            if (string.IsNullOrEmpty(item.StaminaName)) return null;
            return $"{item.StaminaName}";
        }

        internal sealed class EnergyBinderComparer : IComparer<IReadOnlyEnergyBinder>
        {
            public static readonly EnergyBinderComparer Default = new EnergyBinderComparer();
            public int Compare(IReadOnlyEnergyBinder? a, IReadOnlyEnergyBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                return Comparer<EnergyId>.Default.Compare(a.Id, b.Id);
            }
        }

        internal sealed class EnergyBinderIdTieBreakComparer : IComparer<IReadOnlyEnergyBinder>
        {
            private readonly IComparer<IReadOnlyEnergyBinder> _inner;
            public EnergyBinderIdTieBreakComparer(IComparer<IReadOnlyEnergyBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyEnergyBinder? a, IReadOnlyEnergyBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<EnergyId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
